'use strict';
// Village walk graph and player figure as shipped in app.js (generated by scripts/art/village; obstacle checks live in
// scripts/art/village/test_walk.py, which sees the scene's footprints).
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('fs'),path=require('path');
const stat=path.join(__dirname,'../../qw_farm/static');
const app=fs.readFileSync(path.join(stat,'app.js'),'utf8'),css=fs.readFileSync(path.join(stat,'style.css'),'utf8');
const value=name=>{const i=app.indexOf(`const ${name}=`);return eval('('+app.slice(app.indexOf('=',i)+1,app.indexOf(';\n',i))+')');};

test('walk graph: one connected network inside the world, compact integers',()=>{
 const W=value('VILLAGE_WALK'),n=W.n.length/2;
 assert.ok(n>20&&W.e.length%2===0&&W.n.length%2===0);
 assert.ok([...W.n,...W.e].every(Number.isInteger),'integers only');
 for(let i=0;i<W.n.length;i+=2)assert.ok(W.n[i]>=0&&W.n[i]<=2400&&W.n[i+1]>=0&&W.n[i+1]<=1800,'node inside the 2400x1800 world');
 assert.ok(W.e.every(i=>i>=0&&i<n));
 const adj=Array.from({length:n},()=>[]);for(let k=0;k<W.e.length;k+=2){adj[W.e[k]].push(W.e[k+1]);adj[W.e[k+1]].push(W.e[k]);}
 const seen=new Set([0]),todo=[0];while(todo.length)for(const m of adj[todo.pop()])if(!seen.has(m)){seen.add(m);todo.push(m);}
 assert.equal(seen.size,n,'every node reachable');
 for(const q of W.z)assert.equal(q.length,8,'walkable areas are quads');
});
test('walk graph: an approach node for every place the player is sent to',()=>{
 const W=value('VILLAGE_WALK'),n=W.n.length/2;
 const want=[...Object.keys(value('VILLAGE_SPOTS')),...value('VILLAGE_PLACES').map(p=>'place:'+p[0]),...value('VILLAGE_VISITOR_SPOTS').map((_,i)=>'visitor:'+i),'gate','hall','start'];
 assert.deepEqual(Object.keys(W.a).sort(),want.sort());
 for(const k of want)assert.ok(Number.isInteger(W.a[k])&&W.a[k]<n);
});
test('player figure: generated farm-style frames, mirrored for walking left, steps only while walking',()=>{
 const svg=value('VILLAGE_PLAYER_SVG');
 for(const f of ['vp-stand','vp-stepA','vp-stepB'])assert.match(svg,new RegExp(`<g class="${f}">`));
 assert.doesNotMatch(svg,/stroke="#fff/,'no white outlines');
 assert.match(app,/player\.innerHTML=VILLAGE_PLAYER_SVG/);
 assert.match(css,/\.village-player\[data-face=left\] \.vp-art\{transform:scaleX\(-1\)\}/);
 assert.match(css,/\.vp-stepA,\.vp-stepB\{display:none\}/);
 assert.match(css,/prefers-reduced-motion:no-preference\)\{[^@]*\.is-walking \.vp-stand\{display:none\}/);
});
